// POST /runs 는 303 으로 /runs/<run_id> 를 돌려준다.
// 리다이렉트를 따라가지 않게 해두었으므로 Location 헤더에서 run_id 를 꺼낸다.
// 따라가면 HTML 페이지만 받아서 어느 실행인지 알 수 없다.
const r = $input.first().json;
const headers = r.headers || {};
const loc = headers.location || headers.Location || '';
const runId = loc.split('/').filter(Boolean).pop() || '';
const ok = r.statusCode === 303 || r.statusCode === 302;

if (!ok || !runId) {
  throw new Error(`제작 시작 실패 — status=${r.statusCode} location="${loc}". 앱과 터널이 살아 있는지 확인할 것.`);
}

return [{
  json: {
    started_at: new Date().toISOString(),
    status: r.statusCode,
    run_id: runId,
    run_url: `http://localhost:8765/runs/${runId}`,
    note: '조사를 마치면 waiting_for_user 로 멈춘다. 사람이 답할 때까지 진행하지 않는다.'
  }
}];
